import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import AppLayout from "@/components/AppLayout.vue";
import * as echarts from "echarts";
import request from "@/utils/axios"; // 导入axios实例

export default {
  name: "AnalyticsView",
  components: {
    AppLayout
  },
  data() {
    return {
      filterForm: {
        timeRange: "30days",
        department: ["outpatient"]
      },
      trendChartType: "daily",
      charts: {
        trendChart: null,
        diseaseDistributionChart: null,
        ageDistributionChart: null,
        genderDistributionChart: null
      },
      anomalyCases: [],
      isLoading: {
        patient: false,
        diagnose: false,
        anomaly: false
      },
      patientData: {
        diseaseDistribution: {},
        genderDistribution: [],
        ageDistribution: []
      },
      diagnoseData: {
        normal: [],
        unusual: []
      }
    };
  },
  watch: {
    trendChartType() {
      this.handleTrendTypeChange();
    }
  },
  methods: {
    async updateCharts() {
      await this.fetchPatientData();
      await this.fetchDiagnoseData();
      this.renderTrendChart();
      this.updateDiseaseDistributionChart();
      this.updateAgeDistributionChart();
      this.updateGenderDistributionChart();
      await this.updateAnomalyCases();
    },
    resetFilter() {
      this.filterForm = {
        timeRange: "30days",
        department: ["outpatient"]
      };
      this.updateCharts();
    },
    percentFormat(percentage) {
      return percentage + "%";
    },
    getConfidenceColor(confidence) {
      if (confidence < 60) {
        return "#F56C6C";
      } else if (confidence < 80) {
        return "#E6A23C";
      } else {
        return "#67C23A";
      }
    },
    viewAnomalyDetail(row) {
      this.$router.push(`/reports/detail/${row.id}`);
    },
    exportData(type) {
      this.$message.success(`数据已导出为${type.toUpperCase()}格式`);
    },
    // 初始化图表方法
    initCharts() {
      // 使用setTimeout确保DOM完全渲染并有正确尺寸
      setTimeout(() => {
        if (this.$refs.trendChart && !this.charts.trendChart) {
          try {
            this.charts.trendChart = echarts.init(this.$refs.trendChart);
          } catch (error) {
            console.error("初始化诊断趋势图表失败:", error);
          }
        }
        if (this.$refs.diseaseDistributionChart && !this.charts.diseaseDistributionChart) {
          try {
            this.charts.diseaseDistributionChart = echarts.init(this.$refs.diseaseDistributionChart);
          } catch (error) {
            console.error("初始化疾病分布图表失败:", error);
          }
        }
        if (this.$refs.ageDistributionChart && !this.charts.ageDistributionChart) {
          try {
            this.charts.ageDistributionChart = echarts.init(this.$refs.ageDistributionChart);
          } catch (error) {
            console.error("初始化年龄分布图表失败:", error);
          }
        }
        if (this.$refs.genderDistributionChart && !this.charts.genderDistributionChart) {
          try {
            this.charts.genderDistributionChart = echarts.init(this.$refs.genderDistributionChart);
          } catch (error) {
            console.error("初始化性别分布图表失败:", error);
          }
        }

        // 初始化后立即加载数据
        this.updateCharts();
      }, 300); // 增加延迟以确保DOM尺寸稳定
    },
    // 安全渲染图表的通用方法
    safeRenderChart(chart, option) {
      if (!chart) return false;
      try {
        // 尝试重新获取容器尺寸
        const containerElement = chart.getDom();
        if (!containerElement) {
          console.warn("图表容器不存在，跳过渲染");
          return false;
        }

        // 如果容器尺寸为0，尝试重置大小
        if (containerElement.offsetHeight === 0 || containerElement.offsetWidth === 0) {
          console.warn("图表容器尺寸为0，尝试重置尺寸...");

          // 确保容器有最小高度
          containerElement.style.height = "350px";
          containerElement.style.width = "100%";

          // 触发图表重新计算大小
          chart.resize();
        }

        // 设置图表选项
        chart.setOption(option, true);
        return true;
      } catch (error) {
        console.error("图表渲染失败:", error);
        // 尝试设置一个最小的配置以避免进一步错误
        try {
          chart.setOption({
            title: {
              text: "数据加载失败"
            },
            series: []
          });
        } catch (e) {
          console.error("图表恢复失败:", e);
        }
        return false;
      }
    },
    // 获取患者相关数据
    async fetchPatientData() {
      this.isLoading.patient = true;
      try {
        // 创建FormData对象
        const formData = new FormData();
        formData.append("time", this.getTimeRangeValue());
        const response = await request({
          method: "post",
          url: "/diagram/show/patient",
          headers: {
            "Content-Type": "multipart/form-data"
          },
          data: formData
        });
        if (response && (response.code === 1 || response.code === 200)) {
          // 保存API返回的数据
          this.patientData = {
            diseaseDistribution: response.data?.diseaseDistribution || {
              N: 0.2,
              D: 0.1,
              G: 0.1,
              C: 0.3,
              A: 0.05,
              H: 0.05,
              M: 0.1,
              O: 0.1
            },
            genderDistribution: response.data?.genderDistribution || [0.6, 0.4],
            ageDistribution: response.data?.ageDistribution || [44, 22, 33, 67, 77, 133]
          };

          // 更新各个图表
          this.updateDiseaseDistributionChart();
          this.updateAgeDistributionChart();
          this.updateGenderDistributionChart();
        } else {
          this.$message.error(response?.msg || "获取患者数据失败");
          console.error("患者数据API返回错误:", response);
        }
      } catch (error) {
        console.error("获取患者数据出错:", error);
        this.$message.error("获取患者数据失败，请稍后重试");
      } finally {
        this.isLoading.patient = false;
      }
    },
    // 获取诊断趋势数据
    async fetchDiagnoseData() {
      this.isLoading.diagnose = true;
      try {
        // 创建FormData对象
        const formData = new FormData();

        // 设置时间类型参数（日/月）
        formData.append("timeType", this.trendChartType === "daily" ? "日" : "月");

        // 计算时间范围
        const timeRange = this.getTimeRangeValue();
        formData.append("time", timeRange);

        // 当前日期作为结束日期
        const endDate = new Date();
        let startDate;
        if (this.trendChartType === "daily") {
          // 日视图: 按天数往前推
          startDate = new Date(endDate);
          startDate.setDate(endDate.getDate() - timeRange);
        } else {
          // 月视图: 默认获取最近2个月的数据
          startDate = new Date(endDate);
          startDate.setMonth(endDate.getMonth() - 2);
        }

        // 添加日期范围参数
        formData.append("startDate", startDate.toISOString().split("T")[0]);
        formData.append("endDate", endDate.toISOString().split("T")[0]);
        console.log(`${this.trendChartType}视图, 时间范围: ${this.trendChartType === "daily" ? timeRange + "天" : "12个月"}, 开始: ${startDate.toISOString().split("T")[0]}, 结束: ${endDate.toISOString().split("T")[0]}`);
        const response = await request({
          method: "post",
          url: "/diagram/show/diagnose",
          headers: {
            "Content-Type": "multipart/form-data"
          },
          data: formData
        });
        if (response.code === 1 || response.code === 200) {
          // 保存API返回的数据
          const normalData = response.data.normal || [];
          const unusualData = response.data.unusual || [];

          // 确保数据是数组
          this.diagnoseData = {
            normal: Array.isArray(normalData) ? normalData : [],
            unusual: Array.isArray(unusualData) ? unusualData : []
          };
          console.log("诊断趋势数据:", this.diagnoseData);

          // 更新趋势图表
          this.renderTrendChart();
        } else {
          this.$message.error(response.msg || "获取诊断趋势数据失败");
        }
      } catch (error) {
        console.error("获取诊断趋势数据出错:", error);
        this.$message.error("获取诊断趋势数据失败，请稍后重试");
      } finally {
        this.isLoading.diagnose = false;
      }
    },
    // 根据选择的时间范围返回实际天数
    getTimeRangeValue() {
      switch (this.filterForm.timeRange) {
        case "7days":
          return 7;
        case "30days":
          return 30;
        case "3months":
          return 90;
        case "1year":
          return 365;
        default:
          return 30;
      }
    },
    // 诊断趋势图表
    renderTrendChart() {
      if (!this.$refs.trendChart) {
        return; // 如果DOM元素不存在，则返回
      }

      // 确保图表已初始化
      if (!this.charts.trendChart) {
        try {
          this.charts.trendChart = echarts.init(this.$refs.trendChart);
        } catch (error) {
          console.error("初始化诊断趋势图表失败:", error);
          return;
        }
      }
      const normalData = this.diagnoseData.normal || [];
      const unusualData = this.diagnoseData.unusual || [];

      // 确保数据是有效的数组且长度匹配
      if (!Array.isArray(normalData) || !Array.isArray(unusualData)) {
        console.error("诊断数据无效:", this.diagnoseData);
        return;
      }

      // 获取总数据点数
      const dataPoints = normalData.length;

      // 如果没有数据点，显示空图表并返回
      if (dataPoints === 0) {
        const emptyOption = {
          title: {
            text: this.trendChartType === "daily" ? "每日诊断趋势" : "月度诊断趋势",
            left: "center",
            top: 0,
            textStyle: {
              fontSize: 16,
              fontWeight: "normal"
            }
          },
          grid: {
            left: "3%",
            right: "4%",
            bottom: "3%",
            containLabel: true
          },
          xAxis: {
            type: "category",
            data: ["暂无数据"]
          },
          yAxis: {
            type: "value"
          },
          series: []
        };
        this.safeRenderChart(this.charts.trendChart, emptyOption);
        return;
      }

      // 构建有效的数据数组，确保每个元素都是数字
      const validNormalData = normalData.map(val => isNaN(Number(val)) ? 0 : Number(val));
      const validUnusualData = unusualData.map(val => isNaN(Number(val)) ? 0 : Number(val));

      // 生成日期标签
      const xAxisLabels = [];
      const currentDate = new Date();
      if (this.trendChartType === "daily") {
        // 日视图处理逻辑
        const timeRange = this.getTimeRangeValue();
        const dayInterval = timeRange / Math.max(dataPoints, 1);
        for (let i = 0; i < dataPoints; i++) {
          const date = new Date(currentDate);
          const daysFromEnd = Math.round((dataPoints - 1 - i) * dayInterval);
          date.setDate(date.getDate() - daysFromEnd);
          xAxisLabels.push(`${date.getMonth() + 1}月${date.getDate()}日`);
        }
      } else {
        // 月视图处理逻辑 - 处理数组长度的情况
        console.log(`月视图数据: normal=${JSON.stringify(normalData)}, unusual=${JSON.stringify(unusualData)}, 长度=${dataPoints}`);
        if (dataPoints === 2) {
          // 数据正好是两个月 - 上个月和当前月
          const lastMonth = new Date(currentDate);
          lastMonth.setMonth(currentDate.getMonth() - 1);
          xAxisLabels.push(`${lastMonth.getFullYear()}年${lastMonth.getMonth() + 1}月`);
          xAxisLabels.push(`${currentDate.getFullYear()}年${currentDate.getMonth() + 1}月`);
        } else {
          // 处理其他长度的数组
          for (let i = 0; i < dataPoints; i++) {
            const monthDate = new Date(currentDate);
            monthDate.setMonth(currentDate.getMonth() - (dataPoints - 1 - i));
            xAxisLabels.push(`${monthDate.getFullYear()}年${monthDate.getMonth() + 1}月`);
          }
        }
      }

      // 计算总诊断量
      const totalData = validNormalData.map((normal, index) => {
        const unusual = validUnusualData[index] || 0;
        return normal + unusual;
      });

      // 构建图表配置
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          },
          formatter: params => {
            let result = `${params[0].name}<br/>`;
            params.forEach(param => {
              const value = param.value === undefined ? 0 : param.value;
              result += `${param.seriesName}: <strong>${value}</strong> 例<br/>`;
            });
            return result;
          }
        },
        title: {
          text: this.trendChartType === "daily" ? "每日诊断趋势" : "月度诊断趋势",
          left: "center",
          top: 0,
          textStyle: {
            fontSize: 16,
            fontWeight: "normal"
          }
        },
        legend: {
          data: ["总诊断量", "正常诊断", "异常诊断"],
          top: 25
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: xAxisLabels,
          axisLabel: {
            interval: this.trendChartType === "daily" && xAxisLabels.length > 10 ? "auto" : 0,
            rotate: this.trendChartType === "daily" && xAxisLabels.length > 7 ? 45 : 0
          }
        },
        yAxis: {
          type: "value",
          name: "诊断数量",
          minInterval: 1,
          splitLine: {
            show: true,
            lineStyle: {
              type: "dashed"
            }
          }
        },
        series: [{
          name: "总诊断量",
          type: "line",
          data: totalData,
          smooth: true,
          symbol: "circle",
          symbolSize: 8,
          lineStyle: {
            width: 3,
            color: "#409EFF"
          },
          itemStyle: {
            color: "#409EFF"
          },
          label: {
            show: true,
            position: "top",
            formatter: "{c}",
            fontSize: this.trendChartType === "monthly" ? 14 : 12,
            fontWeight: this.trendChartType === "monthly" ? "bold" : "normal",
            color: "#409EFF"
          }
        }, {
          name: "正常诊断",
          type: "bar",
          stack: "total",
          data: validNormalData,
          itemStyle: {
            color: "#67C23A"
          },
          emphasis: {
            focus: "series"
          },
          label: {
            show: true,
            // 月视图总是显示数据标签
            position: "inside",
            formatter: "{c}",
            fontSize: this.trendChartType === "monthly" ? 14 : 12,
            fontWeight: this.trendChartType === "monthly" ? "bold" : "normal",
            color: "#fff"
          }
        }, {
          name: "异常诊断",
          type: "bar",
          stack: "total",
          data: validUnusualData,
          itemStyle: {
            color: "#F56C6C"
          },
          emphasis: {
            focus: "series"
          },
          label: {
            show: true,
            // 月视图总是显示数据标签
            position: "inside",
            formatter: "{c}",
            fontSize: this.trendChartType === "monthly" ? 14 : 12,
            fontWeight: this.trendChartType === "monthly" ? "bold" : "normal",
            color: "#fff"
          }
        }]
      };

      // 使用安全渲染方法设置图表
      this.safeRenderChart(this.charts.trendChart, option);
    },
    // 图表大小变化处理函数
    handleResize() {
      for (const key in this.charts) {
        if (this.charts[key]) {
          try {
            this.charts[key].resize();
          } catch (error) {
            console.error(`调整${key}图表大小失败:`, error);
          }
        }
      }
    },
    // 疾病分布图表
    updateDiseaseDistributionChart() {
      if (!this.charts.diseaseDistributionChart) {
        this.charts.diseaseDistributionChart = echarts.init(this.$refs.diseaseDistributionChart);
      }
      const diseaseData = this.patientData.diseaseDistribution;
      const diseaseNames = {
        N: "正常",
        D: "糖尿病视网膜病变",
        G: "青光眼",
        C: "白内障",
        A: "AMD",
        H: "高血压视网膜病变",
        M: "近视",
        O: "其他异常"
      };
      const data = Object.entries(diseaseData).map(([key, value]) => {
        // 确保值是数字类型
        const numValue = typeof value === "number" ? value : parseFloat(value);
        return {
          name: diseaseNames[key],
          value: parseFloat((numValue * 100).toFixed(1))
        };
      });
      const option = {
        tooltip: {
          trigger: "item",
          formatter: "{a} <br/>{b}: {c}%"
        },
        legend: {
          orient: "vertical",
          right: 10,
          top: "center",
          data: Object.values(diseaseNames)
        },
        series: [{
          name: "疾病分布",
          type: "pie",
          radius: ["50%", "70%"],
          avoidLabelOverlap: false,
          label: {
            show: true,
            position: "outside",
            formatter: "{b}: {c}%"
          },
          emphasis: {
            label: {
              show: true,
              fontSize: "16",
              fontWeight: "bold"
            }
          },
          data: data
        }]
      };
      this.charts.diseaseDistributionChart.setOption(option);
    },
    // 年龄分布图表
    updateAgeDistributionChart() {
      if (!this.charts.ageDistributionChart) {
        this.charts.ageDistributionChart = echarts.init(this.$refs.ageDistributionChart);
      }
      const ageDistribution = this.patientData.ageDistribution;
      const ageGroupLabels = ["0-18", "19-30", "31-45", "46-60", "61-75", "76+"];
      const option = {
        tooltip: {
          trigger: "axis",
          axisPointer: {
            type: "shadow"
          }
        },
        grid: {
          left: "3%",
          right: "4%",
          bottom: "3%",
          containLabel: true
        },
        xAxis: {
          type: "category",
          data: ageGroupLabels,
          axisLabel: {
            interval: 0
          }
        },
        yAxis: {
          type: "value",
          name: "患者数量",
          minInterval: 1
        },
        series: [{
          name: "患者数量",
          type: "bar",
          data: ageDistribution,
          itemStyle: {
            color: function (params) {
              const colorList = ["#91c7ae", "#749f83", "#ca8622", "#bda29a", "#6e7074", "#546570"];
              return colorList[params.dataIndex % colorList.length];
            }
          },
          label: {
            show: true,
            position: "top"
          }
        }]
      };
      this.charts.ageDistributionChart.setOption(option);
    },
    // 性别分布图表
    updateGenderDistributionChart() {
      if (!this.charts.genderDistributionChart) {
        this.charts.genderDistributionChart = echarts.init(this.$refs.genderDistributionChart);
      }
      const genderDistribution = this.patientData.genderDistribution;
      const maleCount = genderDistribution[0] ? (genderDistribution[0] * 100).toFixed(1) : 0;
      const femaleCount = genderDistribution[1] ? (genderDistribution[1] * 100).toFixed(1) : 0;
      const option = {
        tooltip: {
          trigger: "item",
          formatter: "{a} <br/>{b}: {c}%"
        },
        legend: {
          orient: "horizontal",
          bottom: "bottom",
          data: ["男", "女"]
        },
        color: ["#409EFF", "#FF6B6B"],
        series: [{
          name: "性别分布",
          type: "pie",
          radius: "55%",
          center: ["50%", "45%"],
          data: [{
            value: maleCount,
            name: "男"
          }, {
            value: femaleCount,
            name: "女"
          }],
          label: {
            show: true,
            formatter: "{b}: {c}%"
          },
          emphasis: {
            itemStyle: {
              shadowBlur: 10,
              shadowOffsetX: 0,
              shadowColor: "rgba(0, 0, 0, 0.5)"
            }
          }
        }]
      };
      this.charts.genderDistributionChart.setOption(option);
    },
    // 更新异常病例数据
    async updateAnomalyCases() {
      this.isLoading.anomaly = true;
      try {
        // 创建FormData对象
        const formData = new FormData();
        formData.append("page", 1);
        formData.append("pageSize", 5); // 最多显示5条异常病例

        const response = await request({
          method: "get",
          url: "/diagnosisrecord/unusual/show",
          params: {
            page: 1,
            pageSize: 5
          }
        });
        if (response.code === 1 || response.code === 200) {
          // 处理返回的异常病例数据
          if (response.data && response.data.records) {
            this.anomalyCases = response.data.records.map(record => {
              // 处理置信度，将0-1范围转换为0-100
              const leftConfidence = record.leftConfidence ? Math.round(record.leftConfidence * 100) : 0;
              const rightConfidence = record.rightConfidence ? Math.round(record.rightConfidence * 100) : 0;

              // 确定异常原因
              let anomalyReason = "";
              if (leftConfidence < 60 && rightConfidence < 60) {
                anomalyReason = "双眼诊断置信度低";
              } else if (leftConfidence < 60) {
                anomalyReason = "左眼诊断置信度低";
              } else if (rightConfidence < 60) {
                anomalyReason = "右眼诊断置信度低";
              } else if (record.leftResult !== record.rightResult && record.leftResult !== "正常" && record.rightResult !== "正常") {
                anomalyReason = "左右眼诊断结果差异大";
              } else if (record.cause) {
                anomalyReason = record.cause;
              } else {
                anomalyReason = "其他异常";
              }
              return {
                id: record.patientId || record.id,
                time: record.diagnosisTime,
                leftEye: {
                  diagnosis: record.leftResult || "",
                  confidence: leftConfidence
                },
                rightEye: {
                  diagnosis: record.rightResult || "",
                  confidence: rightConfidence
                },
                anomalyReason: anomalyReason
              };
            });
          } else {
            this.anomalyCases = [];
            console.warn("未收到异常病例数据或数据格式不正确");
          }
        } else {
          this.$message.error(response.msg || "获取异常病例数据失败");
          this.anomalyCases = [];
        }
      } catch (error) {
        console.error("获取异常病例数据出错:", error);
        this.$message.error("获取异常病例数据失败，请稍后重试");
        this.anomalyCases = [];
      } finally {
        this.isLoading.anomaly = false;
      }
    },
    async handleTrendTypeChange() {
      await this.fetchDiagnoseData();
    }
  },
  mounted() {
    // 检查登录状态
    const isLoggedIn = localStorage.getItem("isLoggedIn");
    if (!isLoggedIn) {
      this.$router.push("/login");
      return;
    }

    // 初始化图表，内部会调用updateCharts
    this.initCharts();

    // 响应窗口大小变化
    window.addEventListener("resize", this.handleResize);

    // 添加MutationObserver监控DOM变化
    this.$nextTick(() => {
      if (this.$el) {
        const observer = new MutationObserver(() => {
          this.handleResize();
        });
        observer.observe(this.$el, {
          attributes: true,
          childList: true,
          subtree: true
        });

        // 保存observer引用以便后续清理
        this.domObserver = observer;
      }
    });
  },
  beforeUnmount() {
    // 移除事件监听
    window.removeEventListener("resize", this.handleResize);

    // 清理DOM观察器
    if (this.domObserver) {
      this.domObserver.disconnect();
    }

    // 销毁图表实例
    for (const key in this.charts) {
      if (this.charts[key]) {
        try {
          this.charts[key].dispose();
        } catch (error) {
          console.error(`销毁${key}图表失败:`, error);
        }
      }
    }
  }
};
